import sys
import xml.etree.ElementTree as ET
from datetime import datetime

def main():
    if not sys.stdin.isatty():
        xml_path = sys.stdin.readline().strip()
        if not xml_path:
            with open('config_errors.log', 'a') as log:
                log.write(f"{datetime.now().strftime('%Y-%m-%d %H:%M:%S')} config error\n")
            sys.exit(1)

        try:
            tree = ET.parse(xml_path)
            root = tree.getroot()
            if root.tag != 'config':
                with open('config_errors.log', 'a') as log:
                    log.write(f"{datetime.now().strftime('%Y-%m-%d %H:%M:%S')} config error\n")
                sys.exit(1)

            for service in root.findall('service'):
                name = service.get('name')
                host = service.get('host')
                port = service.get('port')
                if not all([name, host, port]):
                    with open('config_errors.log', 'a') as log:
                        log.write(f"{datetime.now().strftime('%Y-%m-%d %H:%M:%S')} config error\n")
                    sys.exit(1)

            for service in root.findall('service'):
                print(f"{service.get('name')} {service.get('host')}:{service.get('port')}")

        except (IOError, ET.ParseError):
            with open('config_errors.log', 'a') as log:
                log.write(f"{datetime.now().strftime('%Y-%m-%d %H:%M:%S')} config error\n")
            sys.exit(1)

if __name__ == "__main__":
    main()
